 exists(select 1 from public.portal_members m where m.email=lower(auth.jwt()->>'email') and (m.role in ('owner','admin') or (m.role='manager' and public.manager_portfolio_matches(m.email,m.portfolio_manager,b.manager))))
 or (not p_manager_only and d.recipient_email=lower(auth.jwt()->>'email') and w.contractor_id=d.contractor_id and lower(c.email)=d.recipient_email and w.status<>'Cancelled')
 ));
$function$
